def _is_numpy(v):
    return type(v).__module__.split(".")[0] == "numpy"


def _list_in(values, ctype, to_c, np_kind, per, copy=False):
    """A C pointer and count for a list: a numpy array goes as it is, anything else copied in."""
    if _is_numpy(values) and np_kind is not None:
        import numpy
        array = numpy.array(values, dtype=np_kind, order="C", copy=True if copy else None)
        if array.size == 0:
            return None, 0, True
        if per == 1:
            array = array.reshape(-1)
        elif array.ndim == 1 and array.size == per:
            array = array.reshape(1, per)
        elif array.ndim != 2 or array.shape[1] != per:
            raise MathError(ErrorKind.Argument)
        pointer = array.ctypes.data_as(POINTER(ctype))
        pointer._keep = array
        return pointer, array.shape[0], True
    values = list(values)
    if not values:
        return None, 0, False
    if to_c is None:
        return (ctype * len(values))(*values), len(values), False
    return (ctype * len(values))(*[to_c(v) for v in values]), len(values), False


def _new_list(ctype, n, np_kind, per, as_numpy):
    """Room for n values a call writes, as a numpy array when numpy came in, and its C pointer."""
    if as_numpy and np_kind is not None:
        import numpy
        array = numpy.zeros((n, per) if per > 1 else n, dtype=np_kind)
        pointer = array.ctypes.data_as(POINTER(ctype))
        return array, pointer
    buffer = (ctype * n)()
    return buffer, buffer


def _list_out(buffer, to_py, size):
    if _is_numpy(buffer):
        return buffer if size is None else buffer[:size]
    items = buffer if size is None else buffer[:size]
    return list(items) if to_py is None else [to_py(x) for x in items]


def _mask_out(buffer, size):
    if _is_numpy(buffer):
        return buffer if size is None else buffer[:size]
    data = bytes(buffer)
    return data if size is None else data[:size]


def _mesh(vertices, vertex_count, triangles, triangle_count):
    if triangle_count % 3:
        raise MathError(ErrorKind.Argument)
    return _RantMeshView(vertices, vertex_count, triangles, triangle_count // 3)


def _prism(p):
    base, count, _np = _list_in(p.base.points, _RantDouble2, _c_Double2, "float64", 2)
    view = _RantPrismView(_c_Pose(p.pose), _RantPolygon2DView(base, count), p.height)
    view._keep = base
    return view


def _prism_answer(v):
    points = [_py_Double2(v.base.points[i]) for i in range(v.base.count)]
    return Prism(_py_Pose(v.pose), Polygon2D(points), v.height)


@dataclass
class Matrix:
    """A dense matrix of doubles, rows one after another."""
    rows: int = 0
    cols: int = 0
    data: list = field(default_factory=list)


def _matrix(m):
    """The C view of a Matrix or a two dimensional numpy array, and its shape."""
    if _is_numpy(m):
        import numpy
        array = numpy.array(m, dtype="float64", order="C")
        if array.ndim != 2:
            raise MathError(ErrorKind.Argument)
        view = _RantMatrixView(array.ctypes.data_as(POINTER(c_double)), array.shape[0], array.shape[1])
        view._keep = array
        return view, view, True
    if len(m.data) != m.rows * m.cols:
        raise MathError(ErrorKind.Argument)
    data = (c_double * len(m.data))(*m.data)
    view = _RantMatrixView(data, m.rows, m.cols)
    view._keep = data
    return view, view, False


def _matrix_out(rows, cols, as_numpy):
    if as_numpy:
        import numpy
        array = numpy.zeros((rows, cols), dtype="float64")
        return array, _RantMatrixView(array.ctypes.data_as(POINTER(c_double)), rows, cols)
    data = (c_double * (rows * cols))()
    return Matrix(rows, cols, data), _RantMatrixView(data, rows, cols)


def _matrix_answer(out):
    if not _is_numpy(out):
        out.data = list(out.data)
    return out


def _bytes_in(data):
    """A C pointer to read a buffer through, with what keeps it alive. Reading never copies bytes."""
    if isinstance(data, bytes):
        return ctypes_cast_bytes(data), len(data)
    if _is_numpy(data):
        return data.ctypes.data_as(POINTER(c_uint8)), data.nbytes
    view = memoryview(data).cast("B") if not isinstance(data, (list, tuple)) else None
    if view is None or view.readonly:
        return _bytes_in(bytes(data))
    return (c_uint8 * view.nbytes).from_buffer(view), view.nbytes


def ctypes_cast_bytes(data):
    from ctypes import cast
    pointer = cast(c_char_p(data), POINTER(c_uint8))
    pointer._keep = data
    return pointer


def _bytes_mut(holder, name):
    """The same for a buffer a call writes to, turned writable in place when it was not."""
    data = getattr(holder, name)
    if _is_numpy(data):
        return data.ctypes.data_as(POINTER(c_uint8)), data.nbytes
    if not isinstance(data, bytearray):
        data = bytearray(data)
        setattr(holder, name, data)
    return (c_uint8 * len(data)).from_buffer(data), len(data)


def _image(_view, image):
    pointer, size = _bytes_in(image.data)
    view = _RantImageView(image.width, image.height, image.stride, int(image.format), pointer, size)
    view._keep = pointer
    return view


def _image_mut(_view, image):
    pointer, size = _bytes_mut(image, "data")
    view = _RantImageView(image.width, image.height, image.stride, int(image.format), pointer, size)
    view._keep = pointer
    return view


def _image_out(fmt, width, height):
    size = _lib.rant_image_bytes(int(fmt), width, height)
    data = bytearray(size)
    pointer = (c_uint8 * size).from_buffer(data) if size else None
    out = Image(width, height, 0, ImageFormat(int(fmt)), data)
    view = _RantImageView(width, height, 0, int(fmt), pointer, size)
    view._keep = pointer
    return out, view


def _image_copy(part):
    out, view = _image_out(part.format, part.width, part.height)
    _check(_lib.rant_image_convert(byref(part), byref(view)))
    return out


def _field(f):
    return PointField(f.name[:f.name_len].decode(), f.offset, ScalarKind(f.kind), f.count)


def _cloud_like(view):
    fields = [_field(view.fields[i]) for i in range(view.field_count)]
    return PointCloud(Transform(), 0, fields, view.point_step, False, b"")


def _cloud(cloud, writes=False):
    fields = (_RantPointFieldView * len(cloud.fields))()
    keep = []
    for i, f in enumerate(cloud.fields):
        name = f.name.encode()
        keep.append(name)
        fields[i] = _RantPointFieldView(name, len(name), f.offset, int(f.kind), f.count)
    pointer, size = _bytes_mut(cloud, "data") if writes else _bytes_in(cloud.data)
    view = _RantPointCloudView(fields, len(cloud.fields), cloud.point_step, pointer, size)
    view._keep = (fields, keep, pointer)
    return view


def _grid(grid, writes=False):
    fields = (_RantGridFieldView * len(grid.fields))()
    keep = []
    for i, f in enumerate(grid.fields):
        name = f.name.encode()
        pointer, size = _bytes_mut(f, "data") if writes else _bytes_in(f.data)
        keep += [name, pointer]
        fields[i] = _RantGridFieldView(name, len(name), int(f.kind), pointer, size)
    view = _RantGridView(_c_Pose(grid.origin.pose), grid.resolution, grid.cells_x, grid.cells_y, grid.cells_z, fields, len(grid.fields))
    view._keep = (fields, keep)
    return view


def _scan(scan):
    ranges, count, _np = _list_in(scan.ranges, c_float, None, "float32", 1)
    view = _RantLaserScanView(scan.angle_min, scan.angle_step, scan.range_min, scan.range_max, scan.echoes, ranges, count)
    view._keep = ranges
    return view


def _detections(view_type, to_c, detections):
    items = (view_type * len(detections))()
    keep = []
    for i, d in enumerate(detections):
        label = d.label.encode()
        keep.append(label)
        items[i] = view_type(to_c(d.bounds), label, len(label), d.score)
    items._keep = keep
    return items


@dataclass
class FitOptions:
    """How a fit treats its points. All default, every point counts alike."""
    weights: object = None    # one per point: how many times its squared error counts
    tolerance: float = 0.0    # above 0, RANSAC: a point farther than this from a model is an outlier of it
    tries: int = 0            # the most models RANSAC tries, 0 for 1000
    seed: int = 0             # RANSAC's random draws: the same seed gives the same answer
    inliers: object = None    # one per point, a bytearray or numpy array: gets 1 within tolerance of the answer, else 0


@dataclass
class AlignOptions:
    """How points_align pairs points. All default, each pairs with its nearest."""
    max_distance: float = 0.0  # above 0, a source point with no target point this near is left out
    iterations: int = 0        # the most rounds, 0 for 50
    normals: object = None     # one per target point: each pair counts by its distance along the normal
    inliers: object = None     # one per source point, a bytearray or numpy array: gets 1 when the answer pairs it, else 0
    error: float = None        # set by the call: the RMS distance of the pairs of the answer


def _inliers_in(options, count):
    if options.inliers is None:
        return None
    pointer, size = _bytes_mut(options, "inliers")
    if size != count:
        raise MathError(ErrorKind.Argument)
    return pointer


def _fit_options(options, count):
    if options is None:
        return None
    weights, n, _np = (None, 0, False) if options.weights is None else _list_in(options.weights, c_double, None, "float64", 1)
    if weights is not None and n != count:
        raise MathError(ErrorKind.Argument)
    inliers = _inliers_in(options, count)
    view = _RantFitOptions(weights, options.tolerance, options.tries, options.seed, inliers)
    view._keep = (weights, inliers)
    return pointer(view)


def _fit_done(options, view):
    pass


def _align_options(options, source, target):
    if options is None:
        return None
    normals, n, _np = (None, 0, False) if options.normals is None else _list_in(options.normals, _RantDouble3, _c_Double3, "float64", 3)
    if normals is not None and n != target:
        raise MathError(ErrorKind.Argument)
    inliers = _inliers_in(options, source)
    error = c_double(0.0)
    view = _RantAlignOptions(options.max_distance, options.iterations, normals, inliers, pointer(error))
    view._keep = (normals, inliers, error)
    holder = pointer(view)
    holder._error = error
    return holder


def _align_done(options, holder):
    if options is not None:
        options.error = holder._error.value


class KdTree:
    """A kd tree over a copy of some points, freed with the object or at the end of a with. Queries
    never change it, so threads may share one."""
    def __init__(self, handle):
        self._handle = handle

    def close(self):
        handle, self._handle = self._handle, None
        if handle:
            _lib.rant_kdtree_destroy(handle)

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()

    def __del__(self):
        self.close()


class Shape:
    """Any shape behind one type, made by a shape_from_ call. It keeps its own copy of any list."""
    def __init__(self, raw, *keep):
        self._raw = raw
        self._keep = keep


class Shape2D:
    """The same in 2D."""
    def __init__(self, raw, *keep):
        self._raw = raw
        self._keep = keep



