def quaternion_to_euler(q: Quaternion, order: EulerOrder) -> List[float]:
    """The middle angle is in [-pi/2, pi/2] for three axes and [0, pi] for a repeated one, the others in
    (-pi, pi]. Where the middle angle locks the outer two, the third is 0."""
    o0 = (c_double * 3)()
