def polynomial_fit(x: Sequence[float], y: Sequence[float], degree: int, options: Optional[FitOptions] = None) -> List[float]:
    """y = c[0] + c[1] x + ... + c[degree] x^degree nearest the points by their error in y, into degree + 1
    coefficients. Needs degree + 1 points with different x."""
