    c_y, n_y, np_y = _list_in(y, c_double, None, 'float64', 1)
    c_options = _fit_options(options, n_x)
    o0, p0 = _new_list(c_double, degree + 1, 'float64', 1, np_x or np_y)
    _check(_lib.rant_polynomial_fit(c_x, c_y, _same_count(n_x, n_y), degree, c_options, p0))
    _fit_done(options, c_options)
    return _list_out(o0, None, None)

